module TopModule (
    input  logic        clk,
    input  logic        reset,
    input  logic [7:0]  in,
    output logic [23:0] out_bytes,
    output logic        done
);

    typedef enum logic [1:0] {
        S_WAIT1 = 2'd0,
        S_WAIT2 = 2'd1,
        S_WAIT3 = 2'd2
    } state_t;

    state_t      state;
    logic [7:0]  b1, b2, b3;
    logic [23:0] out_bytes_reg;
    logic        done_reg;

    always_ff @(posedge clk) begin
        if (reset) begin
            state         <= S_WAIT1;
            b1            <= 8'h0;
            b2            <= 8'h0;
            b3            <= 8'h0;
            out_bytes_reg <= 24'h0;
            done_reg      <= 1'b0;
        end else begin
            done_reg <= 1'b0;
            case (state)
                S_WAIT1: begin
                    if (in[3]) begin
                        b1    <= in;
                        state <= S_WAIT2;
                    end
                end
                S_WAIT2: begin
                    b2    <= in;
                    state <= S_WAIT3;
                end
                S_WAIT3: begin
                    b3            <= in;
                    out_bytes_reg <= {b1, b2, in};
                    done_reg      <= 1'b1;
                    state         <= S_WAIT1;
                end
            endcase
        end
    end

    assign out_bytes = out_bytes_reg;
    assign done      = done_reg;

endmodule

